package Collections;

public class GenericsExamples {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		// Autoboxing   Primitives to Wrapper conversioon 
		int a = 45;
		Integer i = a;
		System.out.println(i);
		
		
		// Unboxing     Wrapper to Primitive conversion
		Integer j = 65;
		int t = j;

	}

}
